#include "rl/pond_ppo_task.h"
#include "motor/heading_request_observation.h"
#include "nn/mlp_cpu.h"
#include "core/checkpoint.h"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <cstring>
namespace p=cudarl::physics;namespace po=cudarl::pond_motor_observation;namespace pt=cudarl::rl::pond_ppo_task;
namespace pr=cudarl::pond_runtime;namespace cp=cudarl::checkpoint;namespace fs=std::filesystem;
void require(bool yes,const char* why){if(!yes)throw std::runtime_error(why);}
void record(std::ostream& o,int id,int control,const pr::World&w,const pt::Task&t,const float* command){const auto& s=w.motor.physical;const auto&b=s.body;o<<"{\"case\":"<<id<<",\"control\":"<<control<<",\"values\":[";bool first=true;const auto emit=[&](double v){if(!first)o<<',';first=false;o<<v;};for(float v:{b.position.x,b.position.y,b.position.z,b.orientation.x,b.orientation.y,b.orientation.z,b.orientation.w})emit(v);for(float v:b.angle)emit(v);for(float v:b.velocity)emit(v);for(float v:s.held_targets)emit(v);for(float v:w.motor.reference_rate)emit(v);for(float v:s.last_actual_torques)emit(v);for(int j=0;j<4;++j)emit(command[j]);emit(b.work);emit(b.travel);emit(s.time_seconds);emit(w.inspection.lower_gap_m);emit(w.inspection.upper_gap_m);o<<"],\"heading\":["<<t.request.request.heading.x<<','<<t.request.request.heading.y<<','<<t.request.request.heading.z<<"]}\n";}
int main(int argc,char**argv){try{require(argc==4,"Use policy unique-output --pure|--run");const bool run=std::string(argv[3])=="--run";require(run||std::string(argv[3])=="--pure","Explicit mode required");const fs::path out=argv[2];require(!fs::exists(out)&&fs::create_directories(out),"Unique output required");const auto bytes=cp::read(argv[1]);cp::Reader r{bytes};for(int i=0;i<12;++i)(void)r.value<uint32_t>();(void)r.value<uint64_t>();(void)r.array<uint8_t>();const auto hashes=r.value<uint32_t>();for(uint32_t i=0;i<hashes;++i)(void)r.array<uint8_t>();const auto weights=r.array<float>();(void)r.array<float>();const float gain=r.value<float>();(void)r.value<float>();r.finish();require(weights.size()==2532&&gain==.26211655139923096f,"Original actor/gain required");cudarl::nn::CpuMlp<float>actor{{{41,32,32,4},{cudarl::nn::Activation::Tanh,cudarl::nn::Activation::Tanh,cudarl::nn::Activation::Identity}}};actor.params()=weights;
 uint64_t assertions=0;for(int pose=0;pose<4;++pose){pr::World w;pt::Task t;t.kind=pt::Turn;auto&s=w.motor.physical;require(po::initialize(pose,false,s.body,s.held_targets,w.motor.reference_rate,s.last_actual_torques,t.request),"Pure fixture");for(float y:{-.002f,0.f,.002f}){s.body.position.y+=y;float a[41]{},b[41]{};require(pt::observe(t,w,a)&&cudarl::heading_request_observation::observe(t.request,s.body,s.held_targets,w.motor.reference_rate,s.last_actual_torques,b),"Pure observation");require(std::memcmp(a,b,sizeof(a))==0,"Turn adapter differs");assertions+=41;}}
 if(!run){std::ofstream f(out/"result.json");f<<"{\"passed\":true,\"pure_observation_scalar_comparisons\":"<<assertions<<",\"physical_controls\":0,\"optimizer_calls\":0}\n";return 0;}
 std::ofstream trace(out/"reference.jsonl");trace<<std::setprecision(17);uint64_t controls=0,substeps=0;bool passed=true;const auto start=std::chrono::steady_clock::now();std::ofstream cases(out/"cases.csv");cases<<"case,pose,turn_deg,controls,passed,late_speed,course_error,depth,tilt\n";
 for(int id=0;id<6;++id){const bool hold=id==4,turn=id<4;const int pose=turn?(id/2?3:0):0,horizon=hold?1280:turn?400:160;pr::World w;pt::Task t;t.kind=hold?pt::Hold:pt::Straight;auto&s=w.motor.physical;require(po::initialize(pose,hold,s.body,s.held_targets,w.motor.reference_rate,s.last_actual_torques,t.request),"Fixture initialization");s.paused=false;require(pr::prepare(w),"Native prepare");float command[4]{};record(trace,id,0,w,t,command);const float degrees=id%2?5.f:-5.f;double vx=0,vz=0;int late=0;float depth=0,tilt=0,hold_speed=0,anchor=0;bool complete=true;
  for(int k=1;k<=horizon;++k){require(controls<3040&&substeps+10<=30400,"Reference budget");require(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<60,"Reference wall cap");if(turn&&k==41){t.kind=pt::Turn;t.turn_radians=degrees*po::pi/180.f;}float observation[41]{};require(pt::observe(t,w,observation),"Reference observation");actor.forward(observation,1);for(int j=0;j<4;++j)command[j]=tanhf((hold?gain:1.f)*actor.output()[j]);const auto before=w.motor.attempted_substeps;++controls;const bool accepted=pr::step(w,command);substeps+=w.motor.attempted_substeps-before;if(!accepted){complete=false;passed=false;break;}++t.episode_controls;++t.request.controls;record(trace,id,k,w,t,command);const auto z=po::measure(t.request,s.body);depth=fmaxf(depth,z.depth_m);tilt=fmaxf(tilt,z.tilt_deg);hold_speed=fmaxf(hold_speed,p::norm(z.velocity_m_s));anchor=fmaxf(anchor,p::norm(z.hold_error_m));if(k>320&&turn){vx+=z.velocity_m_s.x;vz+=z.velocity_m_s.z;++late;}}
  const double speed=late?hypot(vx,vz)/late:0,wanted=atan2(-double(t.request.request.heading.z),double(t.request.request.heading.x)),actual=atan2(-vz,vx),angle=fabs(atan2(sin(actual-wanted),cos(actual-wanted)))*180/po::pi;const bool good=complete&&depth<=.001&&tilt<=10&&(!turn||(speed>=.006&&angle<=5))&&(!hold||(hold_speed<=.0005&&anchor<=.002));passed=passed&&good;cases<<id<<','<<pose<<','<<(turn?degrees:0)<<','<<s.control_steps<<','<<good<<','<<speed<<','<<angle<<','<<depth<<','<<tilt<<'\n';if(!complete)break;}
 std::ofstream f(out/"result.json");f<<"{\"passed\":"<<(passed?"true":"false")<<",\"reference_controls\":"<<controls<<",\"reference_substeps\":"<<substeps<<",\"pure_observation_scalar_comparisons\":"<<assertions<<",\"optimizer_calls\":0}\n";return passed?0:2;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
